using System;

namespace StdbModule;

public static partial class ItalianQuotes
{
    public static class ItaloCalvino
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "A un certo punto era solo questo rapporto a interessarmi, la mia storia diventava soltanto la storia della penna d'oca della monaca che correva sul foglio bianco.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Le amicizie sono sempre legate soprattutto a una stagione della vita e la nostra a quei nostri anni di miseria del dopoguerra, i cui ricordi restano folti e vivi sebbene sospesi in una nuvola quasi intemporale, come ricordi d'infanzia.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Certe cose sulla vita partigiana nessuno le ha mai dette, nessuno ha mai scritto un racconto che sia anche la storia del sangue nelle vene, delle sostanze nell'organismo.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Che si sia tardato ad ascoltarlo e comprenderlo non fa che provare quant'era in avanti rispetto alla coscienza dei tempi.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Ci metto molto a iniziare se ho l'idea per un romanzo, trovo ogni scusa possibile per non lavorarci. Una volta iniziato, so essere molto veloce.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Dati biografici: io sono ancora di quelli che credono, con Croce, che di un autore contano solo le opere. Perciò dati biografici non ne do, o li do falsi, o comunque cerco sempre di cambiarli da una volta all'altra.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Dietro il milite delle Brigate nere più onesto, più in buonafede, più idealista, c'erano i rastrellamenti, le operazioni di sterminio, le camere di tortura, le deportazioni e l'Olocausto; dietro il partigiano più ignaro, più ladro, più spietato, c'era la lotta per una società pacifica e democratica, ragionevolmente giusta, se non proprio giusta in senso assoluto, chè di queste non ce ne sono.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Era ora. Da vent'anni la letteratura italiana ha uno scrittore che non assomiglia a nessun altro, inconfondibile in ogni sua frase, un inventore inesauribile e irresistibile nel gioco del linguaggio e delle idee...", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Il fantastico, contrariamente a quel che si può credere, richiede mente lucida, controllo della ragione sull'ispirazione istintiva o inconscia, disciplina stilistica; richiede di saper nello stesso tempo distinguere e mescolare finzione e verità, gioco e spavento, fascinazione e distacco, cioè leggere il mondo su molteplici livelli e in molteplici linguaggi simultaneamente.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Il genere umano è una zona del vivente che va definita circoscrivendone i confini.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Il luogo ideale per me è quello in cui è più naturale vivere da straniero.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Io sono la pecora nera, l'unico letterato della famiglia.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "La prima parte dell'Isola del Tesoro, quando ancora il meccanismo dell'avventura non è scattato, e regna ancora il senso dell'attesa, si può dire sia la più bella.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Le notizie di nuovi lanci spaziali sono episodi d'una lotta di supremazia terrestre e come tali interessano solo la storia dei modi sbagliati con cui ancora i governi e gli stati maggiori pretendono di decidere le sorti del mondo passando sopra la testa dei popoli.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Ma la luna dei poeti ha qualcosa a che vedere con le immagini lattiginose e bucherellate che i razzi trasmettono? Forse non ancora; ma il fatto che siamo obbligati a ripensare la luna in un modo nuovo ci porterà a ripensare in un modo nuovo tante cose.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Lui capì tutto o quasi del nostro mondo, ma sporgendosi da un'estrema ringhiera dell'Ottocento. Noi vediamo il mondo precipitando nella tromba delle scale.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Secondo: puntare solo sulle cose difficili, eseguite alla perfezione, le cose che richiedono sforzo; diffidare della facilità, della faciloneria, del fare tanto per fare. E combattere l'astrattezza del linguaggio che ci viene imposta ormai da tutte le parti. Puntare sulla precisione, tanto nel linguaggio quanto nelle cose che si fanno.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Terzo: sapere che tutto quello che abbiamo può esserci tolto da un momento all'altro. Con questo non dico mica di rinunciare a niente; anzi, godiamocelo più che mai, però sapendo che da un momento all'altro tutto quello che abbiamo può sparire in una nuvola di fumo.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Nell'eros come nella ghiottoneria, il piacere è fatto di precisione.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Nella mia vita ho incontrato donne di grande forza. Non potrei vivere senza una donna al mio fianco. Sono solo un pezzo d'un essere bicefalo e bisessuato, che è il vero organismo biologico e pensante.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Noi le parole di Matteo Salvatore le dobbiamo ancora inventare.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Oggi il linguaggio politico italiano si è molto complicato, tecnicizzato, intellettualizzato, e credo che tenda a saldarsi in un arco che comprende cattolici e marxisti [...] più a non dire che a dire [...] il linguaggio \"obiettivo\" del telegiornale, quando riassume i discorsi dei leaders politici: tutti ridotti a minime variazioni della stessa combinazione di termini anodini, incolori e insapori.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Per il giovane, la donna è quel che sicuramente c'è.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Quando ho cominciato a scrivere \"Il visconte dimezzato\", volevo soprattutto scrivere una storia divertente per divertire me stesso e possibilmente anche gli altri; avevo questa immagine di un uomo tagliato in due ed ho pensato che questo tema dell'uomo tagliato in due, dell'uomo dimezzato fosse un tema significativo, avesse un significato contemporaneo: tutti ci sentiamo in qualche modo incompleti, tutti realizziamo una parte di noi stessi e non l'altra.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Questa dell'amore per le cose di cui parla è una caratteristica che bisogna tener presente se si vuole riuscire a definire la singolarità dell'operazione letteraria di Levi. Perché quest'uomo che si dice sempre che mette se stesso al centro d'ogni narrazione, che fa scaturire sempre attorno alla sua presenza incontri straordinari, è poi lo scrittore piú dedito alle cose, al mondo oggettivo, alle persone.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Tutta la sua opera mira all'enciclopedia [...]. Si parla sempre dell'impareggiabile fantasia di Verne nel prevedere le invenzioni scientifiche. In realtà era un grande lettore di riviste scientifiche, che arricchiva di quello che via via veniva a sapere sulle ricerche in corso.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Tutto può cambiare, ma non la lingua che ci portiamo dentro, anzi che ci contiene dentro di sé come un mondo più esclusivo e definitivo del ventre materno.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Un libro (io credo) è qualcosa con un principio e una fine (anche se non è un romanzo in senso stretto), è uno spazio in cui il lettore deve entrare, girare, magari perdersi, ma a un certo punto trovare un'uscita, o magari parecchie uscite, la possibilità di aprirsi una strada per venirne fuori.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Zig zag tracciato dai cavalli al galoppo e dalle intermittenze del cuore umano.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "La vita, pensò il nudo, era un inferno, con rari richiami d'antichi felici paradisi.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Così la macchina dell'oppressione sempre si volta contro chi la serve.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Ma tale inesauribile cosa è la libertà dell'uomo, che pure in queste condizioni il pensiero di Pietro riusciva a tessere la sua ragnatela da una macchina all'altra, a fluire continuo come il filo di bocca al ragno, e in mezzo a quella geometria di passi gesti sguardi e riflessi egli a tratti si ritrovava padrone di sé e tranquillo come un nonno campagnolo che esce di mattino tardo sotto la pergola, e mira il sole, e fischia al cane, e sorveglia i nipoti che si dondolano ai rami, e guarda giorno per giorno maturare i fichi.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Mentone non mi attraeva più: perché io avevo ancora quel bisogno d'amici che è proprio dei giovani, cioè il bisogno di dare un senso a quel che vivono parlandone con altri; ossia ero lontano dall'autosufficienza virile, che s'acquista con l'amore, fatto insieme d'integrazione e solitudine.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "C'era la guerra, e tutti ne eravamo presi, e ormai sapevo che avrebbe deciso delle nostre vite. Della mia vita; e non sapevo come.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "La presenza di estranei addormentati suscita negli animi onesti un naturale rispetto, e noi nostro malgrado ne eravamo intimiditi.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Amedeo si sentiva in una condizione perfetta: la pagina scritta gli apriva la vera vita, profonda e appassionante, e alzando gli occhi ritrovava un casuale ma gradevole accostarsi di colori e sensazioni, un mondo accessorio e decorativo, che non poteva impegnarlo in nulla.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Di fatto, ogni silenzio consiste nella rete di rumori minuti che l'avvolge: il silenzio dell'isola si staccava da quello del calmo mare circostante perché era percorso da fruscii vegetali, da versi d'uccelli o da un improvviso frullo d'ali.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Quinto reagiva sempre buttandosi dall'altra parte, abbracciando tutto quello che era nuovo, in contrasto, tutto quel che faceva violenza, e anche adesso, lì, a scoprire l'avvento d'una classe nuova del dopoguerra, d'imprenditori improvvisati e senza scrupoli, egli si sentiva preso da qualcosa che somigliava ora a un interesse scientifico (\"assistiamo a un importante fenomeno sociologico, mio caro...\") ora a un contraddittorio compiacimento estetico.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "«Un tempo solo chi godeva d'una rendita agricola poteva fare l'intellettuale, – pensò Quinto. – La cultura paga ben caro l'essersi liberata da una base economica. Prima viveva sul privilegio, però aveva radici solide. Ora gli intellettuali non sono borghesi e non sono proletari.»", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "E io restavo senza parola, perché capivo che la cucina era il solo luogo di tutta la casa in cui quella donna veramente vivesse, e il resto, le stanze adorne e continuamente spazzolate e incerate erano una specie di opera d'arte in cui lei riversava tutti i suoi sogni di bellezza, e per coltivare la perfezione di quelle stanze si condannava a non viverci, a non entrarci mai come padrona ma solo come donna di fatica, e il resto della giornata a passarlo nell'unto e nella polvere.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Ci sono quelli che si condannano al grigiore della vita più mediocre perché hanno avuto un dolore, una sfortuna; ma ci sono anche quelli che lo fanno perché hanno avuto più fortuna di quella che si sentivano di reggere.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Il vero modo d'accostarci a questo libro è quindi quello di considerarlo una specie di Alice nel paese delle meraviglie o di Peter Pan o di Barone di Münchhausen, cioè di riconoscerne la filiazione da quei classici dell'umorismo poetico e fantastico, da quei libri scritti per gioco, che sono tradizionalmente destinati allo scaffale dei ragazzi.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "La prima lezione che potremmo trarre dal libro è che la disobbedienza acquista un senso solo quando diventa una disciplina morale più rigorosa e ardua di quella a cui si ribella.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Le imprese che si basano su di una tenacia interiore devono essere mute e oscure; per poco uno le dichiari o se ne glori, tutto appare fatuo, senza senso o addirittura meschino.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Un gentiluomo [...] è tale stando in terra come stando in cima agli alberi [...] se si comporta rettamente.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Anche quando pare di poche spanne, un viaggio può restare senza ritorno.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Il bassotto alzò il muso verso di lui, con lo sguardo dei cani quando non capiscono e non sanno che possono aver ragione a non capire.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "L'Abate passò il resto dei suoi giorni tra carcere e convento in continui atti d'abiura, finché non morì, senza aver capito, dopo una vita intera dedicata alla fede, in che cosa mai credesse, ma cercando di credervi fermamente fino all'ultimo.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Capì questo: che le associazioni rendono l'uomo più forte e mettono in risalto le doti migliori delle singole persone, e dànno la gioia che raramente s'ha restando per proprio conto, di vedere quanta gente c'è onesta e brava e capace e per cui vale la pena di volere cose buone (mentre vivendo per proprio conto capita più spesso il contrario, di vedere l'altra faccia della gente, quella per cui bisogna tener sempre la mano alla guardia della spada).", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Quando ho più idee degli altri, do agli altri queste idee, se le accettano; e questo è comandare.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Insomma, gli era presa quella smania di chi racconta storie e non sa mai se sono più belle quelle che gli sono veramente accadute e che a rievocarle riportano con sé tutto un mare d'ore passate, di sentimenti minuti, tedii, felicità, incertezze, vanaglorie, nausee di sé, oppure quelle che ci s'inventa, in cui si taglia giù di grosso, e tutto appare facile, ma poi più si svaria più ci s'accorge che si torna a parlare delle cose che s'è avuto o capito in realtà vivendo.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Ma in tutta quella smania c'era un'insoddisfazione più profonda, una mancanza, in quel cercare gente che l'ascoltasse c'era una ricerca diversa. Cosimo non conosceva ancora l'amore, e ogni esperienza, senza quella, che è? Che vale aver rischiato la vita, quando ancora della vita non conosci il sapore?", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Chi vuole guardare bene la terra deve tenersi alla distanza necessaria.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Ai lutti succedono presto o tardi eventi lieti, è legge della vita.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Cosimo tutti i giorni era sul frassino a guardare il prato come se in esso potesse leggere qualcosa che da tempo lo struggeva dentro: l'idea stessa della lontananza, dell'incolmabilità, dell'attesa che può prolungarsi oltre la vita.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Si conobbero. Lui conobbe lei e se stesso, perché in verità non s'era mai saputo. E lei conobbe lui e se stessa, perché pur essendosi saputa sempre, mai s'era potuta riconoscere così.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Perché mi fai soffrire?\n– Perché ti amo.\nOra era lui ad arrabbiarsi: – No, non mi ami! Chi ama vuole la felicità, non il dolore.\n– Chi ama vuole solo l'amore, anche a costo del dolore.\n– Mi fai soffrire apposta, allora.\n– Sì, per vedere se mi ami.\nLa filosofia del Barone si rifiutava d'andar oltre. – Il dolore è uno stato negativo dell'anima.\n– L'amore è tutto.\n– Il dolore va sempre combattuto.\n– L'amore non si rifiuta a nulla.\n– Certe cose non le ammetterò mai.\n– Sì che le ammetti, perché mi ami e soffri.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Tu ragioni troppo. Perché mai l'amore va ragionato?\n– Per amarti di più. Ogni cosa, a farla ragionando, aumenta il suo potere.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Le imprese più ardite vanno vissute con l'animo più semplice.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "E lei: – Tu non credi che l'amore sia dedizione assoluta, rinuncia di sé...\nEra lì sul prato, bella come mai, e la freddezza che induriva appena i suoi lineamenti e l'altero portamento della persona sarebbe bastato un niente a scioglierli, e riaverla tra le braccia...", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Tutte belle cose, però io avevo l'impressione che in quel tempo mio fratello non solo fosse del tutto ammattito, ma andasse anche un poco imbecillendosi, cosa questa più grave e dolorosa, perché la pazzia è una forza della natura, nel male o nel bene, mentre la minchioneria è una debolezza della natura, senza contropartita.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Chi sta in alto è ben in vista da ogni parte, [...] mentre c'è chi striscia per nascondere il viso.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "– So che per certe sorta di persone è un punto d'onore tenere la faccia in ombra.\n– Quali, di grazia?\n– Le spie, a dirne una!", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Se alzi un muro, pensa a ciò che resta fuori!", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Viviamo in un paese dove si verificano sempre le cause e non gli effetti.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Si sa che i rivoluzionari sono più formalisti dei conservatori.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "La gioventù va via presto sulla terra, figuratevi sugli alberi, donde tutto è destinato a cadere: foglie, frutti.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Ora io non so che cosa ci porterà questo secolo decimonono, cominciato male e che continua sempre peggio. Grava sull'Europa l'ombra della Restaurazione; tutti i novatori – giacobini o bonapartisti che fossero – sconfitti; l'assolutismo e i gesuiti rianno il campo; gli ideali della giovinezza, i lumi, le speranze del nostro secolo decimottavo, tutto è cenere.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Ombrosa non c'è più. Guardando il cielo sgombro, mi domando se davvero è esistita. Quel frastaglio di rami e foglie, biforcazioni, lobi, spiumii, minuto e senza fine, e il cielo solo a sprazzi irregolari e ritagli, forse c'era solo perché ci passasse mio fratello col suo leggero passo di codibugnolo, era un ricamo fatto sul nulla che assomiglia a questo filo d'inchiostro, come l'ho lasciato correre per pagine e pagine, zeppo di cancellature, di rimandi, di sgorbi nervosi, di macchie, di lacune, che a momenti si sgrana in grossi acini chiari, a momenti si infittisce in segni minuscoli come semi puntiformi, ora si ritorce su se stesso, ora si biforca, ora collega grumi di frasi con contorni di foglie o di nuvole, e poi s'intoppa, e poi ripiglia a attorcigliarsi, e corre e corre e si sdipana e avvolge un ultimo grappolo insensato di parole idee sogni ed è finito.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "La forza dell'eremita si misura non da quanto lontano è andato a stare, ma dalla poca distanza che gli basta per staccarsi dalla città, senza mai perderla di vista.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "C'è un modo colpevole di abitare la città: accettare le condizioni della bestia feroce dandogli in pasto i nostri figli. C'è un modo colpevole di abitare la solitudine: credersi tranquillo perché la bestia feroce è resa inoffensiva da una spina nella zampa.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Sullo scudo c'era disegnato uno stemma tra due lembi d'un ampio manto drappeggiato, e dentro lo stemma s'aprivano altri due lembi di manto con in mezzo uno stemma più piccolo, [...] e in mezzo ci doveva essere chissà che cosa, ma non si riusciva a scorgere, tanto il disegno diventava minuto.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Era un'epoca in cui la volontà e l'ostinazione d'esserci, di marcare un'impronta, di fare attrito con tutto ciò che c'è, non veniva usata interamente, dato che molti non se ne facevano nulla – per miseria o ignoranza o perché invece tutto riusciva loro bene lo stesso – e quindi una certa quantità ne andava persa nel vuoto.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Cosa può sapere del mondo una povera suora?", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Tu butti fuori certi peti più puzzolenti dei miei, cadavere. Non so perché tutti ti compiangano. Cosa ti manca? Prima ti muovevi, ora il tuo movimento passa ai vermi che tu nutri.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Questa storia che ho intrapreso a scrivere è ancora più difficile di quanto io non pensassi. Ecco che mi tocca rappresentare la più gran follia dei mortali, la passione amorosa, dalla quale il voto, il chiostro e il naturale pudore m'hanno fin qui scampata.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Bradamante non era diversa da loro, in fondo: forse questi suoi vagheggiamenti di severità e rigore se li era messi in testa per contrastare la sua vera natura. Per esempio, se c'era una sciattona in tutto l'esercito di Francia, era lei.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Così sempre corre il giovane verso la donna: ma è davvero amore per lei a spingerlo? o non è amore soprattutto di sé, ricerca d'una certezza d'esserci che solo la donna gli può dare?", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Non c'è difesa né offesa, non c'è senso di nulla. La guerra durerà fino alla fine dei secoli e nessuno vincerà o perderà, resteremo fermi gli uni di fronte agli altri per sempre. E senza gli uni gli altri non sarebbero nulla e ormai sia noi che loro abbiamo dimenticato perché combattiamo...", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "A ognuna è data la sua penitenza, qui in convento, il suo modo di guadagnarsi la salvezza eterna. A me è toccata questa di scriver storie: è dura, è dura.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Contro a tutte le regole imperiali d'etichetta, Carlomagno s'andava a mettere a tavola prima dell'ora, quando ancora non c'erano altri commensali. Si siede e comincia a spilluzzicare pane o formaggio o olive o peperoncini, insomma tutto quel che è già in tavola.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Rambaldo esce dalla battaglia vittorioso e incolume; ma l'armatura, la candida intatta impeccabile armatura di Agilulfo adesso è tutta incrostata di terra, spruzzata di sangue nemico, costellata d'ammaccature, bugni, sgraffi, slabbri, il cimiero mezzo spennato, l'elmo storto, lo scudo scrostato proprio in mezzo al misterioso stemma.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Se infelice è l'innamorato che invoca baci di cui non sa il sapore, mille volte più infelice è chi questo sapore gustò appena e poi gli fu negato.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Anche ad essere si impara...", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "La pagina ha il suo bene solo quando la volti e c'è la vita dietro che spinge e scompiglia tutti i fogli del libro. La penna corre spinta dallo stesso piacere che ti fa correre le strade.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Questo romanzo è il primo che ho scritto; quasi posso dire la prima cosa che ho scritto, se si eccettuano pochi racconti. Che impressione mi fa, a riprenderlo in mano adesso? Più che come un'opera mia lo leggo come un libro nato anonimamente dal clima generale d'un'epoca, da una tensione morale, da un gusto letterario che era quello in cui la nostra generazione si riconosceva, dopo la fine della Seconda Guerra Mondiale.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Personaggi, paesaggi, spari, didascalie politiche, voci gergali, parolacce, lirismi, armi ed amplessi non erano che colori della tavolozza, note del pentagramma, sapevamo fin troppo bene che quel che contava era la musica e non il libretto.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Il «neorealismo» non fu una scuola. [...] Fu un insieme di voci, in gran parte periferiche, una molteplice scoperta delle diverse Italie, anche – o specialmente – delle Italie fino allora più inedite per la letteratura. Senza la varietà di Italie sconosciute l'una all'altra – o che si supponevano sconosciute –, senza la varietà dei dialetti e dei gerghi da far lievitare e impastare nella lingua letteraria, non ci sarebbe stato «neorealismo».", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Avevo un paesaggio. Ma per poterlo rappresentare occorreva che esso diventasse secondario rispetto a qualcos'altro: a delle persone, a delle storie. La Resistenza rappresentò la fusione tra paesaggio e persone.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "A poco più d'un anno dalla Liberazione già la «rispettabilità ben pensante» era in piena riscossa, e approfittava d'ogni aspetto contingente di quell'epoca – gli sbandamenti della gioventù postbellica, la recrudescenza della delinquenza, la difficoltà di stabilire una nuova legalità – per esclamare: «Ecco, noi l'avevamo sempre detto, questi partigiani, tutti così, non ci vengano a parlare di Resistenza, sappiamo bene che razza d'ideali...»", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Ebbene: cosa cambia? Anche in chi si è gettato nella lotta senza un chiaro perché, ha agito un'elementare spinta di riscatto umano, una spinta che li ha resi centomila volte migliori di voi, che li ha fatti diventare forze storiche attive quali voi non potrete mai sognarvi di essere!", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "Le letture e l'esperienza di vita non sono due universi ma uno. Ogni esperienza di vita per essere interpretata chiama certe letture e si fonde con esse. Che i libri nascano sempre da altri libri è una verità solo apparentemente in contraddizione con l'altra: che i libri nascano dalla vita pratica e dai rapporti tra gli uomini.", Author = "Italo Calvino" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Italo_Calvino", Text = "In gioventù ogni libro nuovo che si legge è come un nuovo occhio che si apre e modifica la vista degli altri occhi o libri-occhi che si avevano prima.", Author = "Italo Calvino" },
        };
    }
}